"""Download the IBM "Transactions for AML" benchmark (PUBLIC DATA, synthetic, generated by AMLSim; licence
CDLA-Sharing-1.0) and convert it to partitioned Parquet with Dask.

    python src/ingest_dask.py --size medium      # HI-Medium, ~32M rows, 3.0 GB CSV
    python src/ingest_dask.py --size small       # HI-Small, ~5M rows, 0.5 GB CSV (quick runs)
    python src/ingest_dask.py --size small --compare-duckdb   # also time the same conversion in DuckDB

Steps
  1. download once, resumable (curl -C -), cached in data/raw/ (never published)
  2. Dask read_csv with bank codes and account numbers read as TEXT (leading zeros: '020', '03196')
  3. rename the two 'Account' columns to from_account / to_account, parse 'YYYY/MM/DD HH:MM' timestamps
  4. convert every amount to USD with the fixed rates implied by the file's own cross-currency rows
  5. write Parquet partitioned by day (the whole file falls in one calendar month, see docs/assumptions.md)
  6. accounts file: 'Entity Name' is dropped at read time; bank country parsed from 'Bank Name'
  7. log rows read / written, wall time and peak memory to output/ingest_log.csv
"""
import argparse
import json
import shutil
import subprocess
import threading
import time
from pathlib import Path

import dask
import dask.dataframe as dd
import pandas as pd
import psutil

ROOT = Path(__file__).resolve().parents[1]
RAW = ROOT / "data" / "raw"
PARQ = ROOT / "data" / "parquet"
OUT = ROOT / "output"
BASE = "https://huggingface.co/datasets/OsamaMIT/IBM-AML-HI/resolve/main/"
UA = "aml-case-study/1.0"
COLS = ["ts", "from_bank", "from_account", "to_bank", "to_account", "amount_received", "receiving_currency",
        "amount_paid", "payment_currency", "payment_format", "is_laundering"]
DTYPES = {"ts": "string", "from_bank": "string", "from_account": "string", "to_bank": "string",
          "to_account": "string", "amount_received": "float64", "receiving_currency": "string",
          "amount_paid": "float64", "payment_currency": "string", "payment_format": "string", "is_laundering": "int8"}


class PeakMemory:
    """Samples resident memory of this process every 0.2 s (Dask threaded scheduler runs in-process)."""
    def __init__(self):
        self.peak, self._stop = 0, threading.Event()
        self._t = threading.Thread(target=self._run, daemon=True)

    def _run(self):
        p = psutil.Process()
        while not self._stop.is_set():
            self.peak = max(self.peak, p.memory_info().rss)
            time.sleep(0.2)

    def __enter__(self):
        self._t.start()
        return self

    def __exit__(self, *a):
        self._stop.set()
        self._t.join()


def download(name: str) -> Path:
    dest = RAW / name
    RAW.mkdir(parents=True, exist_ok=True)
    if dest.exists() and dest.stat().st_size > 0 and not (RAW / (name + ".part")).exists():
        return dest
    marker = RAW / (name + ".part")
    marker.touch()
    subprocess.run(["curl", "-sSL", "-C", "-", "-A", UA, "--retry", "5", "-o", str(dest), BASE + name], check=True)
    marker.unlink()
    return dest


def fx_rates(ddf) -> pd.DataFrame:
    """USD per unit of each currency, from rows paid in that currency and received in US Dollar."""
    m = (ddf.receiving_currency == "US Dollar") & (ddf.payment_currency != "US Dollar") & (ddf.amount_paid > 0)
    x = ddf[m].assign(r=ddf.amount_received / ddf.amount_paid)
    g = x.groupby("payment_currency").r.agg(["mean", "std", "count"]).compute()
    g = g.rename_axis("currency").reset_index().rename(columns={"mean": "usd_per_unit", "std": "std", "count": "n_rows"})
    return pd.concat([g, pd.DataFrame([{"currency": "US Dollar", "usd_per_unit": 1.0, "std": 0.0, "n_rows": 0}])])


def convert_dask(csv: Path, out_dir: Path) -> dict:
    ddf = dd.read_csv(csv, header=0, names=COLS, dtype=DTYPES, blocksize="64MB")
    rates = fx_rates(ddf)
    rmap = dict(zip(rates.currency, rates.usd_per_unit))
    ts = dd.to_datetime(ddf.ts, format="%Y/%m/%d %H:%M")
    ddf = ddf.assign(ts=ts, day=ts.dt.strftime("%Y-%m-%d"),
                     amount_paid_usd=ddf.amount_paid * ddf.payment_currency.map(rmap, meta=("x", "float64")),
                     amount_received_usd=ddf.amount_received * ddf.receiving_currency.map(rmap, meta=("x", "float64")))
    if out_dir.exists():
        shutil.rmtree(out_dir)
    ddf.to_parquet(out_dir, partition_on=["day"], engine="pyarrow", write_index=False, compression="zstd")
    n_written = int(dd.read_parquet(out_dir, columns=["is_laundering"]).shape[0].compute())
    return {"rates": rates, "rows_written": n_written}


def convert_duckdb(csv: Path, out_dir: Path) -> int:
    import duckdb
    if out_dir.exists():
        shutil.rmtree(out_dir)
    con = duckdb.connect()
    names = ", ".join(f"'{c}'" for c in COLS)
    con.execute(f"""COPY (SELECT *, strftime(strptime(ts, '%Y/%m/%d %H:%M'), '%Y-%m-%d') AS day
                         FROM read_csv('{csv.as_posix()}', header=true, all_varchar=true, names=[{names}]))
                    TO '{out_dir.as_posix()}' (FORMAT parquet, PARTITION_BY (day), COMPRESSION zstd)""")
    return con.execute(f"SELECT count(*) FROM read_parquet('{out_dir.as_posix()}/**/*.parquet')").fetchone()[0]


def csv_rows(csv: Path) -> int:
    n = 0
    with open(csv, "rb") as fh:
        for block in iter(lambda: fh.read(1 << 24), b""):
            n += block.count(b"\n")
    return n - 1  # header


def accounts(size: str):
    name = f"{'HI-Medium' if size == 'medium' else 'HI-Small'}_accounts.csv"
    f = download(name)
    # 'Entity Name' is never loaded (rule: no entity names anywhere downstream)
    a = pd.read_csv(f, usecols=["Bank Name", "Bank ID", "Account Number", "Entity ID"], dtype=str)
    a.columns = ["bank_name", "bank_id", "account", "entity_id"]
    a["bank_country"] = a.bank_name.str.extract(r"^(.*) Bank #")[0].fillna("Unknown")
    a = a.drop(columns="bank_name")
    a.to_parquet(PARQ / "accounts.parquet", index=False)
    return len(a)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--size", choices=["small", "medium"], default="medium")
    ap.add_argument("--compare-duckdb", action="store_true")
    args = ap.parse_args()
    prefix = "HI-Medium" if args.size == "medium" else "HI-Small"
    PARQ.mkdir(parents=True, exist_ok=True)
    OUT.mkdir(parents=True, exist_ok=True)
    csv = download(f"{prefix}_Trans.csv")
    download(f"{prefix}_Patterns.txt")
    shutil.copy(RAW / f"{prefix}_Patterns.txt", PARQ / "patterns.txt")
    n_csv = csv_rows(csv)
    log = []
    dask.config.set(scheduler="threads")
    with PeakMemory() as pm:
        t0 = time.perf_counter()
        res = convert_dask(csv, PARQ / "trans")
        dt = time.perf_counter() - t0
    log.append({"engine": "dask", "dataset": prefix, "rows_in_csv": n_csv, "rows_written": res["rows_written"],
                "seconds": round(dt, 1), "peak_rss_gb": round(pm.peak / 1e9, 2),
                "cores": psutil.cpu_count(), "ram_gb": round(psutil.virtual_memory().total / 1e9, 1)})
    res["rates"].to_csv(PARQ / "fx_rates.csv", index=False)
    res["rates"][["currency", "usd_per_unit", "n_rows"]].to_csv(OUT / "fx_rates_implied.csv", index=False)
    if args.compare_duckdb:
        with PeakMemory() as pm:
            t0 = time.perf_counter()
            n = convert_duckdb(csv, PARQ / "_duckdb_trans")
            dt = time.perf_counter() - t0
        log.append({"engine": "duckdb", "dataset": prefix, "rows_in_csv": n_csv, "rows_written": n,
                    "seconds": round(dt, 1), "peak_rss_gb": round(pm.peak / 1e9, 2),
                    "cores": psutil.cpu_count(), "ram_gb": round(psutil.virtual_memory().total / 1e9, 1)})
        shutil.rmtree(PARQ / "_duckdb_trans")
    n_acc = accounts(args.size)
    (PARQ / "meta.json").write_text(json.dumps({"size": args.size, "dataset": prefix, "rows_in_csv": n_csv,
                                                "accounts_rows": n_acc}, indent=1))
    lg = pd.DataFrame(log)
    old = OUT / "ingest_log.csv"
    if old.exists():
        prev = pd.read_csv(old)
        prev = prev[~prev.set_index(["engine", "dataset"]).index.isin(lg.set_index(["engine", "dataset"]).index)]
        lg = pd.concat([prev, lg])
    lg.to_csv(old, index=False)
    for r in log:
        print(f"{r['engine']}: {r['rows_in_csv']:,} csv rows -> {r['rows_written']:,} parquet rows, "
              f"{r['seconds']} s, peak {r['peak_rss_gb']} GB")
    assert res["rows_written"] == n_csv, "Parquet row count differs from CSV"


if __name__ == "__main__":
    main()
